# Mock it for test purposes

def calculate_stock_volatility(prices):
    # Simple volatility mock: standard deviation of returns
    if len(prices) < 2:
        return 0.0
    returns = [(prices[i+1]/prices[i] - 1) for i in range(len(prices)-1)]
    if not returns:
        return 0.0
    mean = sum(returns)/len(returns)
    return (sum((r-mean)**2 for r in returns)/len(returns))**0.5

