def parse_sensor_reading(sensor_string):
    '''
    Create a function called parse_sensor_reading that takes a string like 'T:25.5|H:60|TS:1234567890'. 
    Split by '|' to get parts. For each part, split by ':' to get key and value. 
    Return dict with 'temperature', 'humidity', 'timestamp' keys. 
    If a value cannot be converted to float/int, set to None. 
    Handle T as float, H as float, TS as int.

    >>> parse_sensor_reading('T:25.5|H:60|TS:1234567890')
    {'temperature': 25.5, 'humidity': 60.0, 'timestamp': 1234567890}
    >>> parse_sensor_reading('T:abc|H:60.1|TS:xyz')
    {'temperature': None, 'humidity': 60.1, 'timestamp': None}
    '''

    # Chain-of-Thought:
    # 1. Split the input string by '|'
    # 2. For each part, split by ':' to get key & value
    # 3. Map keys 'T' -> 'temperature', 'H' -> 'humidity', 'TS' -> 'timestamp'
    # 4. Parse values as float (for T & H) or int (for TS)
    # 5. Handle conversion errors; set value to None if failed
    # 6. Return dictionary with all keys, even if missing from input

    result = {'temperature': None, 'humidity': None, 'timestamp': None}
    key_map = {'T': 'temperature', 'H': 'humidity', 'TS': 'timestamp'}

    for part in sensor_string.split('|'):
        if ':' not in part:
            continue
        key, value = part.split(':', 1)
        if key not in key_map:
            continue
        dict_key = key_map[key]
        if key in ('T', 'H'):
            try:
                result[dict_key] = float(value)
            except (ValueError, TypeError):
                result[dict_key] = None
        elif key == 'TS':
            try:
                result[dict_key] = int(value)
            except (ValueError, TypeError):
                result[dict_key] = None

    return result
